def transform(grid):
    """Overlay the shared color from two panels, marking its overlap."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1

    candidates = []
    # A separator is a single-color full row or column whose color appears
    # nowhere outside that line.
    for r in range(h):
        value = grid[r][0]
        if all(x == value for x in grid[r]) and counts[value] == w:
            candidates.append(("h", r))
    for c in range(w):
        value = grid[0][c]
        if all(grid[r][c] == value for r in range(h)) and counts[value] == h:
            candidates.append(("v", c))
    if not candidates:
        raise ValueError("No unique-color separator")

    # The full-length unique-color divider distinguishes itself from any
    # uniform rows/columns that belong to a panel.
    orientation, split = candidates[0]
    if orientation == "h":
        first, second = grid[:split], grid[split + 1:]
        oh, ow = min(len(first), len(second)), w
        first, second = first[:oh], second[:oh]
    else:
        first = [row[:split] for row in grid]
        second = [row[split + 1:] for row in grid]
        oh, ow = h, min(split, w - split - 1)
        first = [row[:ow] for row in first]
        second = [row[:ow] for row in second]

    shared = set(x for row in first for x in row) & set(x for row in second for x in row)
    if not shared:
        raise ValueError("Panels have no shared color")
    color = max(shared, key=lambda x: sum(row.count(x) for row in first) + sum(row.count(x) for row in second))
    return [[3 if first[r][c] == color and second[r][c] == color else color
             for c in range(ow)] for r in range(oh)]


